def q600():

    class Book:

        def __init__(self):
            self.orders = {}
            self.seen = set()
            self.clock = 0

        def cancel(self, key):
            return self.orders.pop(key, None)

        def submit(self, key, side, price, quantity, tif="GTC"):
            if (
                key in self.seen
                or side not in ("buy", "sell")
                or tif not in ("GTC", "IOC", "FOK")
                or (not isinstance(price, int))
                or (not isinstance(quantity, int))
                or (price < 0)
                or (quantity <= 0)
            ):
                raise ValueError("invalid order")
            candidates = [
                (oid, o)
                for oid, o in self.orders.items()
                if o["side"] != side
                and (
                    o["price"] <= price
                    if side == "buy"
                    else o["price"] >= price
                )
            ]
            candidates.sort(
                key=lambda pair: (
                    (
                        pair[1]["price"]
                        if side == "buy"
                        else -pair[1]["price"]
                    ),
                    pair[1]["time"],
                )
            )
            self.seen.add(key)
            if (
                tif == "FOK"
                and sum((o["quantity"] for _, o in candidates)) < quantity
            ):
                return ([], quantity)
            trades = []
            remaining = quantity
            for oid, order in candidates:
                amount = min(remaining, order["quantity"])
                remaining -= amount
                order["quantity"] -= amount
                trades.append((oid, order["price"], amount))
                if order["quantity"] == 0:
                    del self.orders[oid]
                if remaining == 0:
                    break
            if remaining and tif == "GTC":
                self.orders[key] = {
                    "side": side,
                    "price": price,
                    "quantity": remaining,
                    "time": self.clock,
                }
                self.clock += 1
            return (trades, remaining)

    return Book()
